import string

BASE36 = string.digits + string.ascii_uppercase


def to_base36(n: int) -> str:
    """Convert integer to base36 string."""
    if n == 0:
        return "0"
    result = []
    while n > 0:
        result.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(result))


def from_base36(s: str) -> int:
    """Convert base36 string to integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def main():
    last_id = None
    with open("ids.txt") as f:
        for line in f:
            line = line.strip()
            if line:
                last_id = line

    if last_id is None:
        # No ids yet; start from zero
        next_suffix = "0000"
    else:
        suffix = last_id.split("-")[1]
        n = from_base36(suffix)
        n += 1
        next_suffix = to_base36(n).zfill(4).upper()

    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

