import sys

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def next_id(current_suffix):
    """Increment a 4-character base-36 suffix, returning the next suffix."""
    chars = list(current_suffix.upper())
    for i in range(3, -1, -1):
        idx = DIGITS.index(chars[i])
        if idx < 35:
            chars[i] = DIGITS[idx + 1]
            break
        else:
            chars[i] = DIGITS[0]
    else:
        # All digits wrapped — overflow
        raise ValueError("ID overflow: all 4-char combinations exhausted")
    return "".join(chars)

def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_line = lines[-1]
    if not last_line.startswith("ORD-") or len(last_line) != 8:
        sys.exit(f"Invalid last id: {last_line}")

    suffix = last_line[4:]
    next_suffix = next_id(suffix)
    print(f"ORD-{next_suffix}")

if __name__ == "__main__":
    main()
