import sys

# Base36 character set
CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    return sum(CHARS.index(c) * (36 ** i) for i, c in enumerate(reversed(s)))

def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer to a base36 string of the given width."""
    result = []
    for _ in range(width):
        result.append(CHARS[n % 36])
        n //= 36
    return ''.join(reversed(result))

def next_order_id(ids_file: str = 'ids.txt') -> str:
    """Read ids.txt and return the next order ID."""
    try:
        with open(ids_file) as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print(f'Error: {ids_file} not found', file=sys.stderr)
        sys.exit(1)

    if not lines:
        print('Error: ids.txt is empty', file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]
    suffix = last_id[4:]  # Remove 'ORD-' prefix

    current_val = base36_decode(suffix)
    next_val = current_val + 1
    next_suffix = base36_encode(next_val)

    return f'ORD-{next_suffix}'

if __name__ == '__main__':
    result = next_order_id()
    print(result)

