#!/usr/bin/env python3
import sys

def next_id(path="ids.txt"):
    with open(path) as f:
        lines = f.readlines()

    # Find the last line that contains "ORD-"
    last_id = None
    for line in reversed(lines):
        line = line.strip()
        if "ORD-" in line:
            # Take the suffix after ORD-
            parts = line.split("ORD-")
            if len(parts) > 1:
                suffix = parts[-1].split()[0]  # first word after ORD-
                if len(suffix) == 4:
                    last_id = suffix
                    break

    if last_id is None:
        sys.exit("error: no valid ORD-XXXX id found in ids.txt")

    # Base-36 increment
    val = int(last_id, 36)
    val += 1

    # Encode back to 4-char base-36 uppercase
    result = ""
    for _ in range(4):
        rem = val % 36
        if rem < 10:
            result = chr(ord("0") + rem) + result
        else:
