        if "ORD-" in line:
            # Take the suffix after ORD-
            parts = line.split("ORD-")
            if len(parts) > 1:
                suffix = parts[-1].split()[0]  # first word after ORD-
                if len(suffix) == 4:
                    last_id = suffix
                    break

    if last_id is None:
