    val = int(last_id, 36)
    val += 1

    # Encode back to 4-char base-36 uppercase
    result = ""
    for _ in range(4):
        rem = val % 36
        if rem < 10:
            result = chr(ord("0") + rem) + result
        else:
            result = chr(ord("A") + rem - 10) + result
        val //= 36

