import json


def main():
    seen = {}
    with open('events.jsonl', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            row = json.loads(line)
            # keep the last occurrence for each event_id
            seen[row['event_id']] = row

    with open('deduped.jsonl', 'w', encoding='utf-8') as out:
        for event_id in seen:
            out.write(json.dumps(seen[event_id], ensure_ascii=False) + '\n')


if __name__ == '__main__':
    main()

