#!/usr/bin/env python3
"""Read events.jsonl, remove duplicates by event_id (keeping first occurrence),
and write deduped events to deduped.jsonl."""

import json

def main():
    seen = set()
    deduped = []

    with open("events.jsonl", "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                deduped.append(event)

    with open("deduped.jsonl", "w") as f:
        for event in deduped:
            f.write(json.dumps(event) + "\n")

    print(f"Wrote {len(deduped)} unique events to deduped.jsonl")

if __name__ == "__main__":
    main()

