#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"


def sha256_digest(filepath: str) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for root, dirs, files in os.walk(RELEASE_DIR):
        for filename in sorted(files):
            full_path = os.path.join(root, filename)
            relative_path = os.path.relpath(full_path, start=os.getcwd())
            manifest[relative_path] = sha256_digest(full_path)

    with open("manifest.json", "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print("manifest.json written")


if __name__ == "__main__":
    main()

