#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_PATH = "manifest.json"


def sha256_digest(filepath: str) -> str:
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    release_root = os.path.join(os.path.dirname(os.path.abspath(__file__)), RELEASE_DIR)

    for dirpath, _dirnames, filenames in os.walk(release_root):
        for filename in sorted(filenames):
            full_path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(full_path, release_root)
            manifest[rel_path] = sha256_digest(full_path)

    manifest_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), MANIFEST_PATH)
    with open(manifest_path, "w") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")

    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

