#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the hex SHA-256 digest of *path*."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        # Read in chunks so we don't load huge files entirely into memory.
        for chunk in iter(lambda: f.read(2 ** 20), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    if not RELEASE_DIR.is_dir():
        print(f"ERROR: {RELEASE_DIR} does not exist or is not a directory.")
        raise SystemExit(1)

    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            # Use forward-slash paths consistently (POSIX convention).
            key = str(path.as_posix())
            manifest[key] = sha256_digest(path)

    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n"
    )
    print(f"Wrote {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

