"""Generate manifest.json — SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def hex_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} not found")
        raise SystemExit(1)

    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            relative = str(path.relative_to(Path(".")))
            manifest[relative] = hex_digest(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

