#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re
import glob


def report_key(path: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    match = re.search(r"report-(\d+)", os.path.basename(path))
    return int(match.group(1)) if match else 0


def main() -> None:
    report_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")
    files = sorted(glob.glob(os.path.join(report_dir, "report-*.txt")), key=report_key)
    for f in files:
        print(os.path.basename(f))


if __name__ == "__main__":
    main()

