#!/usr/bin/env python3
"""List the file names under reports/, one per line, in report order."""

import os
import re


def natural_key(name: str):
    """Return a sort key that orders embedded numbers numerically."""
    return [int(part) if part.isdigit() else part.lower()
            for part in re.split(r"(\d+)", name)]


def main() -> None:
    reports_dir = "reports"
    try:
        names = sorted(os.listdir(reports_dir), key=natural_key)
    except FileNotFoundError:
        print(f"Error: '{reports_dir}' directory not found.")
        raise SystemExit(1)

