"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str):
    """Parse 'YYYY-MM-DD HH:MM:SS ' prefix from a log line to a datetime."""
    dt = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    return dt.replace(tzinfo=timezone.utc)


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 86400  # 7 days in seconds

    keep = []
    archive = []

    with open("app.log") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                continue
            ts = parse_timestamp(line)
            if ts.timestamp() < cutoff:
                archive.append(line)
            else:
                keep.append(line)

    with open("archive.log", "a") as f:
        for line in archive:
            f.write(line + "\n")

    with open("app.log", "w") as f:
        for line in keep:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

