import sys
from datetime import datetime, timezone

def parse_timestamp(line: str):
    """Extract the datetime from a line starting with YYYY-MM-DD HH:MM:SS."""
    try:
        ts_str = line[:19]
        return datetime.strptime(ts_str, '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None

def main():
    if len(sys.argv) != 2:
        print('Usage: python rotate.py AS_OF', file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    # 7 days before AS_OF, in seconds
    cutoff_ts = as_of - 7 * 86400
    cutoff_dt = datetime.fromtimestamp(cutoff_ts, tz=timezone.utc)

    with open('app.log', 'r') as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        line_stripped = line.rstrip('\n')
        if not line_stripped:
            continue
        dt = parse_timestamp(line_stripped)
        if dt is None:
            # lines without a valid timestamp are kept
            kept.append(line_stripped)
        elif dt < cutoff_dt:
            archived.append(line_stripped)
        else:
            kept.append(line_stripped)

    # Append to archive.log
    if archived:
        with open('archive.log', 'a') as f:
            for line in archived:
                f.write(line + '\n')

    # Rewrite app.log
    with open('app.log', 'w') as f:
        for line in kept:
            f.write(line + '\n')

if __name__ == '__main__':
    main()

