#!/usr/bin/env python3
"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS. Any entry whose timestamp is
strictly older than 7 days before AS_OF is moved to archive.log (appended,
preserving order); app.log is rewritten with the remaining entries in their
original order.
"""

import sys
from datetime import datetime, timedelta

TS_FORMAT = "%Y-%m-%d %H:%M:%S"
HOLD_DAYS = 7


def parse_entry(line: str) -> datetime | None:
    """Parse the leading timestamp of a log line; None if it is malformed."""
    try:
        return datetime.strptime(line[:19], TS_FORMAT)
    except ValueError:
        return None


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: python rotate.py AS_OF", file=sys.stderr)
        return 1

    as_of = int(sys.argv[1])
    cutoff = datetime.fromtimestamp(as_of - HOLD_DAYS * 86400)

    old_entries: list[str] = []
    keep_entries: list[str] = []
    with open("app.log", "r", encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n").rstrip("\r")
            if not line:
                continue
            ts = parse_entry(line)
            if ts is None or ts < cutoff:
                old_entries.append(line)
            else:
                keep_entries.append(line)

    if keep_entries and not old_entries:
        pass  # nothing to rotate; leave files untouched if nothing moved

    if old_entries:
        with open("archive.log", "a", encoding="utf-8") as f:
            for line in old_entries:
                f.write(line + "\n")

    if old_entries:
        with open("app.log", "w", encoding="utf-8") as f:
            for line in keep_entries:
                f.write(line + "\n")

    return 0


if __name__ == "__main__":
    sys.exit(main())
